// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title ChainSignatures
/// @author Relay Protocol
/// @notice Library for encoding JSON requests for chain signatures
library ChainSignatures {
  /// @notice Encodes a JSON request for the signer
  /// @param payloadString The hex string representation of the payload to sign
  /// @param curve The curve to use for signing
  /// @param domainId The domain ID
  /// @return The encoded JSON request
  function encodeJSONRequest(
    string memory payloadString,
    string memory curve,
    string memory signerPath,
    string memory domainId
  ) public pure returns (bytes memory) {
    return
      abi.encodePacked(
        // solhint-disable-next-line quotes
        '{"request":{"payload_v2": { "',
        curve,
        // solhint-disable-next-line quotes
        '":"',
        payloadString,
        // solhint-disable-next-line quotes
        '"},"path":"',
        signerPath,
        // solhint-disable-next-line quotes
        '","domain_id":',
        domainId,
        // solhint-disable-next-line quotes
        "}}"
      );
  }

  /// @notice Converts bytes data to its hex string representation
  /// @param data The bytes data to convert (arbitrary length)
  /// @return The hex string representation of the data
  function stringifyBytes(
    bytes memory data
  ) public pure returns (string memory) {
    bytes16 alphabet = 0x30313233343536373839616263646566; // "0123456789abcdef"
    bytes memory str = new bytes(data.length * 2);
    for (uint256 i = 0; i < data.length; ) {
      uint8 b = uint8(data[i]);
      // precompute offset
      uint256 offset = i << 1; // i * 2
      str[offset] = alphabet[b >> 4]; // high nibble
      str[offset + 1] = alphabet[b & 0x0f]; // low nibble
      unchecked {
        i++;
      }
    }
    return string(str);
  }
}

contracts/ERC20View.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title IHub
/// @author Relay Protocol
/// @notice Interface for the Hub contract
interface IHub {
  /// @notice Returns the balance of a token for an owner
  /// @param owner The owner address
  /// @param id The token ID
  /// @return The balance amount
  function balanceOf(address owner, uint256 id) external view returns (uint256);

  /// @notice Transfers tokens from one address to another
  /// @param sender The sender address
  /// @param receiver The receiver address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return True if successful
  function transferFrom(
    address sender,
    address receiver,
    uint256 id,
    uint256 amount
  ) external returns (bool);

  /// @notice Returns the total supply of a token
  /// @param id The token ID
  /// @return The total supply
  function totalSupply(uint256 id) external view returns (uint256);

  /// @notice Returns the name of a token
  /// @param id The token ID
  /// @return The token name
  function name(uint256 id) external view returns (string memory);

  /// @notice Returns the symbol of a token
  /// @param id The token ID
  /// @return The token symbol
  function symbol(uint256 id) external view returns (string memory);

  /// @notice Returns the decimals of a token
  /// @param id The token ID
  /// @return The token decimals
  function decimals(uint256 id) external view returns (uint8);

  /// @notice Returns the token URI of a token
  /// @param id The token ID
  /// @return The token URI
  function tokenURI(uint256 id) external view returns (string memory);

  /// @notice Returns the allowance of a spender for an owner
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @return The allowance amount
  function allowance(
    address owner,
    address spender,
    uint256 id
  ) external view returns (uint256);

  /// @notice Approves a spender to spend tokens on behalf of owner
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return True if successful
  function approveFor(
    address owner,
    address spender,
    uint256 id,
    uint256 amount
  ) external returns (bool);
}

/// @title ERC20View
/// @author Relay Protocol
/// @notice ERC20-compatible view contract that interfaces with the Hub
contract ERC20View {
  /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an approval is made
  event Approval(address indexed owner, address indexed spender, uint256 value);
  /// @notice Emitted when a transfer occurs
  event Transfer(address indexed from, address indexed to, uint256 value);

  /*//////////////////////////////////////////////////////////////
                            CUSTOM ERRORS
    //////////////////////////////////////////////////////////////*/

  error ERC20ViewInsufficientAllowance(
    address spender,
    uint256 allowance,
    uint256 needed
  );

  /*//////////////////////////////////////////////////////////////
                                STORAGE
    //////////////////////////////////////////////////////////////*/

  /// @notice The Hub contract instance
  IHub public immutable hub;
  /// @notice The token ID this view represents
  uint256 public immutable tokenId;

  /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

  /// @notice Constructor for ERC20View
  /// @param _tokenId The token ID this view represents
  constructor(uint256 _tokenId) {
    hub = IHub(msg.sender);
    tokenId = _tokenId;
  }

  /*//////////////////////////////////////////////////////////////
                          ERC20 IMPLEMENTATION
    //////////////////////////////////////////////////////////////*/

  /// @notice Returns the name of the token
  /// @return The token name
  function name() public view returns (string memory) {
    return hub.name(tokenId);
  }

  /// @notice Returns the symbol of the token
  /// @return The token symbol
  function symbol() public view returns (string memory) {
    return hub.symbol(tokenId);
  }

  /// @notice Returns the decimals of the token
  /// @return The token decimals
  function decimals() public view returns (uint8) {
    return hub.decimals(tokenId);
  }

  /// @notice Returns the token URI
  /// @return The token URI
  function tokenURI() public view returns (string memory) {
    return hub.tokenURI(tokenId);
  }

  /// @notice Returns the total supply of the token
  /// @return The total supply
  function totalSupply() public view returns (uint256) {
    return hub.totalSupply(tokenId);
  }

  /// @notice Returns the balance of an account
  /// @param account The account address
  /// @return The balance amount
  function balanceOf(address account) public view returns (uint256) {
    return hub.balanceOf(account, tokenId);
  }

  /// @notice Returns the allowance amount for a spender
  /// @param owner The owner address
  /// @param spender The spender address
  /// @return The allowance amount
  function allowance(
    address owner,
    address spender
  ) public view returns (uint256) {
    return hub.allowance(owner, spender, tokenId);
  }

  /// @notice Approves a spender to spend tokens
  /// @param spender The spender address
  /// @param value The amount to approve
  /// @return True if successful
  function approve(address spender, uint256 value) public returns (bool) {
    bool success = hub.approveFor(msg.sender, spender, tokenId, value);
    if (success) {
      emit Approval(msg.sender, spender, value);
    }
    return success;
  }

  /// @notice Transfers tokens to another address
  /// @param to The recipient address
  /// @param value The amount to transfer
  /// @return True if successful
  function transfer(address to, uint256 value) public returns (bool) {
    bool success = hub.transferFrom(msg.sender, to, tokenId, value);
    if (success) {
      emit Transfer(msg.sender, to, value);
    }
    return success;
  }

  /// @notice Transfers tokens from one address to another
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount to transfer
  /// @return True if successful
  function transferFrom(
    address from,
    address to,
    uint256 value
  ) public returns (bool) {
    // Check allowance unless the spender is the owner
    if (msg.sender != from) {
      uint256 currentAllowance = hub.allowance(from, msg.sender, tokenId);
      if (currentAllowance < type(uint256).max) {
        if (currentAllowance < value) {
          revert ERC20ViewInsufficientAllowance(
            msg.sender,
            currentAllowance,
            value
          );
        }
        hub.approveFor(from, msg.sender, tokenId, currentAllowance - value);
      }
    }

    // Execute the transfer on the Hub
    bool success = hub.transferFrom(from, to, tokenId, value);
    if (success) {
      emit Transfer(from, to, value);
    }
    return success;
  }

  /*//////////////////////////////////////////////////////////////
                          HUB EVENT EMISSION
    //////////////////////////////////////////////////////////////*/

  /// @notice Emits a transfer event (only callable by the hub)
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount transferred
  function emitTransferEvent(address from, address to, uint256 value) external {
    if (msg.sender == address(hub)) {
      emit Transfer(from, to, value);
    }
  }

  /// @notice Emits an approval event (only callable by the hub)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param value The approved amount
  function emitApprovalEvent(
    address owner,
    address spender,
    uint256 value
  ) external {
    if (msg.sender == address(hub)) {
      emit Approval(owner, spender, value);
    }
  }
}

contracts/PayloadBuilders/SolanaPayloadB.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import {IPayloadBuilder} from "../RelayAllocator.sol";
import {Utils} from "../Utils.sol";

/// @title IRelayAllocator
/// @notice Interface for RelayAllocator contract
// solhint-disable-next-line use-natspec
interface IRelayAllocator {
  /// @notice Returns the owner address of the RelayAllocator contract
  /// @return The address of the contract owner
  function owner() external view returns (address);
}

/// @notice Configuration for a specific chain
struct ChainConfig {
  bytes32 domain; /// @notice Domain separator for the chain
  bytes32 vaultAddress; /// @notice Vault address for the chain
}

/// @title SolanaPayloadBuilder
/// @author Relay Protocol
/// @notice Builds Borsh-encoded payloads for Solana chain withdrawals
contract SolanaPayloadBuilder is IPayloadBuilder {
  error InvalidExpiration();
  error NotRelayAllocatorOwner(address account);
  error ChainNotConfigured(uint256 chainId);

  /// @notice RelayAllocator contract instance
  IRelayAllocator public immutable allocator;

  /// @notice Chain configuration for each chain ID
  mapping(uint256 => ChainConfig) public chainConfigs;

  /// @notice Constructor that initializes the payload builder with allocator
  /// @param _allocator The RelayAllocator contract address
  constructor(IRelayAllocator _allocator) {
    allocator = _allocator;
  }

  /// @notice Modifier to restrict access to allocator owner only
  modifier onlyAllocatorOwner() {
    if (msg.sender != allocator.owner())
      revert NotRelayAllocatorOwner(msg.sender);
    _;
  }

  /// @notice Sets the chain configuration for a specific chain
  /// @param chainId The chain ID
  /// @param domain The domain separator (32 bytes)
  /// @param vaultAddress The vault address (32 bytes)
  function setChainConfig(
    uint256 chainId,
    bytes32 domain,
    bytes32 vaultAddress
  ) external onlyAllocatorOwner {
    chainConfigs[chainId] = ChainConfig({
      domain: domain,
      vaultAddress: vaultAddress
    });
  }

  /// @notice Builds Borsh-encoded payload for Solana withdrawal
  /// @param chainId Chain ID to get domain and vault configuration
  /// @param currency SPL token address (empty for SOL)
  /// @param amount Amount to withdraw
  /// @param receiver Recipient public key
  /// @param data Optional nonce and expiration (empty for defaults)
  /// @return Borsh-encoded transaction payload
  function buildPayload(
    uint256 chainId,
    string calldata /* depository */,
    string memory currency,
    uint256 amount,
    string memory receiver,
    bytes calldata data
  ) external view override returns (bytes memory) {
    // Get chain configuration
    ChainConfig memory config = chainConfigs[chainId];
    if (config.vaultAddress == bytes32(0)) {
      revert ChainNotConfigured(chainId);
    }

    // Parse token address (None means SOL)
    bytes32 tokenPubkey;
    bytes32 recipientPubkey = Utils.hexStringToBytes32(receiver);

    if (bytes(currency).length > 0) {
      tokenPubkey = Utils.hexStringToBytes32(currency);
    }

    // Ensure amount doesn't exceed uint64 max value
    if (amount > type(uint64).max) {
      revert InsufficientAmount(amount);
    }

    uint64 amountU64 = uint64(amount);

    // Parse or generate nonce and expiration
    uint64 nonce;
    int64 expiration;

    if (data.length == 0) {
      // Generate default values if no data provided
      nonce = uint64(
        uint256(keccak256(abi.encodePacked(block.timestamp, block.number)))
      );
      expiration = int64(int256(block.timestamp + 300)); // 5 minutes validity
    } else {
      // Decode provided nonce and expiration
      (nonce, expiration) = abi.decode(data, (uint64, int64));
      if (expiration < int64(int256(block.timestamp))) {
        revert InvalidExpiration();
      }
    }

    // Encode request in Borsh compatible format
    return
      encodeBorsh(
        config.domain,
        recipientPubkey,
        tokenPubkey,
        amountU64,
        nonce,
        expiration,
        config.vaultAddress
      );
  }

  /// @notice Returns message hash to sign for Solana transaction
  /// @param payload Borsh-encoded transaction payload
  /// @return SHA256 hash of the payload
  function hashToSign(
    uint256 /* chainId */,
    string calldata /* depository */,
    bytes calldata payload,
    uint32 /* hashIndex */
  ) external pure override returns (bytes32) {
    return sha256(payload);
  }

  /// @notice Returns cryptographic curve for Solana signing
  /// @return curve "Eddsa" for Solana
  function curve() external pure returns (string memory) {
    return "Eddsa";
  }

  /// @notice Returns blockchain family identifier
  /// @return family "solana-vm" for Solana
  function family() external pure returns (string memory) {
    return "solana-vm";
  }

  /// @notice Encodes Solana TransferRequest in Borsh format
  /// @dev Field order matches Rust struct:
  ///      1. domain, 2. recipient, 3. token, 4. amount, 5. nonce, 6. expiration, 7. vault_address
  /// @param domain Domain separator (32 bytes)
  /// @param recipient Recipient public key (32 bytes)
  /// @param token SPL token public key (zero for SOL)
  /// @param amount Amount to transfer (u64)
  /// @param nonce Unique transaction nonce (u64)
  /// @param expiration Expiration timestamp in seconds (i64)
  /// @param vaultAddress Vault address (32 bytes)
  /// @return Borsh-encoded TransferRequest payload
  function encodeBorsh(
    bytes32 domain,
    bytes32 recipient,
    bytes32 token,
    uint64 amount,
    uint64 nonce,
    int64 expiration,
    bytes32 vaultAddress
  ) internal pure returns (bytes memory) {
    bytes memory result;

    // 1. Domain (32 bytes)
    result = bytes.concat(result, domain);

    // 2. Recipient (32 bytes)
    result = bytes.concat(result, recipient);

    // 3. Token (Option<Pubkey>) - 1 byte discriminant + optional 32 bytes
    if (token == bytes32(0)) {
      // None (0x00) for native SOL
      result = bytes.concat(result, hex"00");
    } else {
      // Some (0x01) for SPL token
      result = bytes.concat(result, hex"01", token);
    }

    // 4. Amount (8 bytes, little-endian u64)
    result = bytes.concat(result, Utils.encodeUint64LE(amount));

    // 5. Nonce (8 bytes, little-endian u64)
    result = bytes.concat(result, Utils.encodeUint64LE(nonce));

    // 6. Expiration (8 bytes, little-endian i64)
    if (expiration < 0) revert InvalidExpiration();
    result = bytes.concat(result, Utils.encodeUint64LE(uint64(expiration)));

    // 7. Vault address (32 bytes)
    result = bytes.concat(result, vaultAddress);

    return result;
  }

  /// @notice Converts hex string to bytes32 (for testing)
  /// @param hexString Hex string to convert
  /// @return bytes32 representation
  function hexStringToBytes32(
    string memory hexString
  ) public pure returns (bytes32) {
    return Utils.hexStringToBytes32(hexString);
  }
}

contracts/RelayAllocator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {
  AuroraSdk,
  NEAR,
  PromiseCreateArgs,
  PromiseResult,
  PromiseResultStatus,
  PromiseWithCallback
} from "./aurora-xcc/AuroraSdk.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {RelayHub} from "./RelayHub.sol";
import {Utils} from "./Utils.sol";
import {ChainSignatures} from "./ChainSignatures.sol";

/// @title IEvmERC20
/// @notice Interface for EVM ERC20 tokens that support withdrawal to NEAR
// solhint-disable-next-line use-natspec
interface IEvmERC20 is IERC20 {
  /// @notice Withdraws tokens to NEAR network
  /// @param recipient The recipient address on NEAR
  /// @param amount The amount to withdraw
  function withdrawToNear(bytes memory recipient, uint256 amount) external;
}

/// @title ISafe
/// @notice Interface for Safe multisig contract
// solhint-disable-next-line use-natspec
interface ISafe {
  /// @notice Checks if an address is an owner of the Safe
  /// @param owner The address to check
  /// @return True if the address is an owner
  function isOwner(address owner) external view returns (bool);
}

/// @title IPayloadBuilder
/// @author Relay Protocol
/// @notice Interface for payload builders that create withdrawal payloads for different chains
interface IPayloadBuilder {
  error InsufficientAmount(uint256 amount);

  /// @notice Builds a withdrawal payload for the specified parameters
  /// @param chainId The destination chain ID
  /// @param depository The depository address
  /// @param currency The currency address
  /// @param amount The amount to withdraw
  /// @param receiver The receiver address
  /// @param data Additional data
  /// @return The built payload
  function buildPayload(
    uint256 chainId,
    string calldata depository,
    string calldata currency,
    uint256 amount,
    string calldata receiver,
    bytes calldata data
  ) external view returns (bytes memory);

  /// @notice Returns the hashes that need to be signed for the payload
  /// @param chainId The destination chain ID
  /// @param depository The depository address
  /// @param payload The payload to sign
  /// @return Array of hashes to sign
  function hashToSign(
    uint256 chainId,
    string calldata depository,
    bytes calldata payload,
    uint32 hashIndex
  ) external view returns (bytes32);

  /// @notice Returns the curve used for signing
  /// @return The curve name
  function curve() external pure returns (string memory);

  /// @notice Returns the family of the payload builder
  /// @return The family name
  function family() external pure returns (string memory);
}

// NEAR gas settings
struct GasSettings {
  uint64 signGas;
  uint64 callbackGas;
}

/// @title Allocator
/// @author Relay Protocol
/// @notice Manages cross-chain withdrawal requests and payload signing using NEAR MPC signer
contract RelayAllocator is AccessControl, Ownable, EIP712 {
  using AuroraSdk for NEAR;
  using AuroraSdk for PromiseCreateArgs;
  using AuroraSdk for PromiseWithCallback;
  using AuroraSdk for PromiseResult;
  using Strings for uint256;
  using ECDSA for bytes32;

  /// @notice Emitted when the global delay is changed
  event DelayChanged(uint256 delay);
  /// @notice Emitted when a depository-specific delay is changed
  event DepositoryDelayChanged(
    uint256 chainId,
    string depository,
    uint256 delay
  );
  /// @notice Emitted when the hub contract is set
  event HubSet(address hub);
  /// @notice Emitted when the signature fee is changed
  event SignatureFeeChanged(uint256 fee);

  // EIP712
  /// @notice The signing domain for EIP712
  string public constant SIGNING_DOMAIN = "RelayAllocator";
  /// @notice The signature version for EIP712
  string public constant SIGNATURE_VERSION = "1";
  /// @notice The type hash for SubmitWithdrawRequest
  bytes32 public constant PAYLOAD_TYPEHASH =
    keccak256(
      "SubmitWithdrawRequest(uint256 chainId,string depository,string currency,uint256 amount,address spender,string receiver,bytes data,bytes32 nonce)"
    );

  // roles
  /// @notice Role for approved withdrawers
  bytes32 public constant APPROVED_WITHDRAWER_ROLE =
    keccak256("APPROVED_WITHDRAWER_ROLE");
  /// @notice Role for administrators
  bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

  /// @notice Precompute the hash of the curve
  bytes32 private constant ECDSA_HASH = keccak256("Ecdsa");

  /// @notice Gas for withdrawals to NEAR
  uint64 public immutable NEAR_WITHDRAW_GAS = 2_000_000_000_000;

  /// @notice The NEAR signer account address
  string public nearSigner;

  /// @notice The Aurora SDK NEAR instance
  NEAR public near;

  /// @notice Global delay for withdrawal requests
  uint256 public delay;

  /// @notice Path used by the MPC signer to sign the payload
  string public signerPath;

  /// @notice Fee in wNEAR to cover gas on NEAR
  uint256 public signatureFee;

  /// @notice Delay configuration struct
  struct DelayConfig {
    uint256 delay;
    bool isSet;
  }

  /// @notice Mapping of delays per-depository : chain ID => depository => delay
  mapping(uint256 => mapping(string => DelayConfig)) public depositoryDelays;

  /// @notice Address of the hub contract
  address public hub;

  /// @notice Mapping of payload builders: chain ID => depository => payload builder address
  mapping(uint256 => mapping(string => address)) public payloadBuilders;

  /// @notice Signed payloads: withdrawal request hash => hash to sign => signed payload
  mapping(bytes32 => mapping(bytes32 => bytes)) public signedPayloads;

  /// @notice Payload timestamps: withdrawal request hash => timestamp when payload becomes ready
  mapping(bytes32 => uint256) public payloadTimestamps;

  /// @notice Unsigned payloads: withdrawal request hash => payload
  mapping(bytes32 => bytes) public payloads;

  /// @notice Used nonces for replay protection: sender => nonce => whether it has been used
  mapping(address => mapping(bytes32 => bool)) public usedNonces;

  /// @notice Emitted when a payload builder is set for a chain and depository
  event PayloadBuilderSet(
    uint256 indexed chainId,
    string indexed depository,
    address indexed builder
  );

  /// @notice Emitted when a payload is built
  event PayloadBuilt(
    bytes32 indexed withdrawRequestHash,
    bytes payload,
    uint256 timestamp
  );

  /// @notice Emitted when a payload is signed
  event PayloadWithdrawSigned(
    bytes32 indexed withdrawRequestHash,
    bytes32 indexed hashToSign,
    bytes signedPayload
  );

  // errors
  error NotMultisigOwner(address account);
  error CallerIsNotApproved(address account);
  error NoPayloadBuilder(uint256 chainId, string depository);
  error PayloadNotReady(bytes32 withdrawRequestHash);
  error PayloadAlreadyBuilt(bytes32 withdrawRequestHash);
  error PayloadAlreadySigned(bytes32 withdrawRequestHash);
  error SignCallbackFailed(bytes32 withdrawRequestHash);
  error WithdrawalRequestFailed();

  struct SubmitWithdrawRequest {
    uint256 chainId; // ChainId of the destination chain on which the user will withdraw
    string depository; // Address of the depository account as a string so we can support non EVM
    string currency; // Address of the currency to be withdrawn, as a string so we can support non EVM. Use zero address for native.
    uint256 amount; // Amount to withdraw
    address spender; // Address of the account that owns the balance in the Hub contract (can be an alias)
    string receiver; // Address of the account on the destination chain as a string so we can support non EVM
    bytes data; // Additional data to be passed to the payload builder
    bytes32 nonce; // Nonce for replay protection
  }

  /// @notice Constructor for RelayAllocator contract
  /// @param _owner The owner of the contract
  /// @param _delay The global delay for withdrawal requests
  /// @param _signer The NEAR signer account
  /// @param _wNEAR The wNEAR token address
  constructor(
    address _owner,
    uint256 _delay,
    string memory _signer,
    address _wNEAR
  ) Ownable(_owner) EIP712(SIGNING_DOMAIN, SIGNATURE_VERSION) {
    // roles
    _setRoleAdmin(APPROVED_WITHDRAWER_ROLE, ADMIN_ROLE);
    _grantRole(ADMIN_ROLE, _owner);

    // delay
    delay = _delay;

    // set signer and Aurora SDK
    nearSigner = _signer;
    near = AuroraSdk.initNear(IERC20(_wNEAR)); // this does an unlimited approval for wNEAR for the precompile.

    // compute path at deployment
    signerPath = Strings.toHexString(uint160(address(this)), 20);

    // Fee - default to 0
    signatureFee = 0;
  }

  modifier onlyMultisigOwner() {
    if (!ISafe(owner()).isOwner(msg.sender))
      revert NotMultisigOwner(msg.sender);
    _;
  }

  /// @notice initializes XCC sub-account for the contract
  /// You need to approve 2 wNEAR for the CS Signer to init the sub-account
  /// @notice This calls the simplest possible contract on NEAR to bootstrap itself and initialize the XCC subaccount.
  function init() public onlyOwner {
    // this will initialize the XCC sub-account on NEAR
    // 2 Near are required for storage staking
    near.wNEAR.transferFrom(
      msg.sender,
      address(this),
      uint256(2_000_000_000_000_000_000_000_000)
    );

    // Make a cross-contract call to trigger sub-account creation.
    // we are calling the "system" account with empty data on NEAR to trigger sub-account creation
    // as "system" is a special account that is not part of the chain state.
    PromiseCreateArgs memory initCall = near.call(
      "system",
      "",
      "",
      0,
      500_000_000_000
    );
    initCall.transact();
  }

  /// @notice Grants a role to an address
  /// @param role The role to grant
  /// @param newOwner The address to grant the role to
  function grantRole(bytes32 role, address newOwner) public override onlyOwner {
    _grantRole(role, newOwner);
  }

  /// @notice Revokes a role from an address
  /// @param role The role to revoke
  /// @param newOwner The address to revoke the role from
  function revokeRole(
    bytes32 role,
    address newOwner
  ) public override onlyOwner {
    _revokeRole(role, newOwner);
  }

  /// @notice prevents a withdrawer from withdrawing
  /// @param withdrawer Address to prevent from withdrawing
  function suspend(address withdrawer) public onlyMultisigOwner {
    _revokeRole(APPROVED_WITHDRAWER_ROLE, withdrawer);
  }

  /// @notice Sets the hub contract address
  /// @param _fee Signature fee in wNEAR
  function setSignatureFee(uint256 _fee) external onlyOwner {
    signatureFee = _fee;
    emit SignatureFeeChanged(signatureFee);
  }

  /// @notice Sets the hub contract address
  /// @param _hub Hub contract address
  function setHub(address _hub) external onlyOwner {
    hub = _hub;
    emit HubSet(hub);
  }

  /// @notice Sets the global delay for withdrawal requests
  /// @param _delay Delay in seconds
  function setDelay(uint256 _delay) public onlyOwner {
    delay = _delay;
    emit DelayChanged(delay);
  }

  /// @notice sets or updates the delay for a specific chain and depository
  /// @param chainId chain ID
  /// @param depository address of the depository contract as string
  /// @param _delay delay in seconds
  function setDepositoryDelay(
    uint256 chainId,
    string calldata depository,
    uint256 _delay
  ) external onlyOwner {
    depositoryDelays[chainId][depository].delay = _delay;
    depositoryDelays[chainId][depository].isSet = true;
    emit DepositoryDelayChanged(chainId, depository, _delay);
  }

  /// @notice sets or updates the payload builder for a specific chain
  /// @param chainId chain ID
  /// @param builder address of the payload builder contract
  function setPayloadBuilder(
    uint256 chainId,
    string calldata depository,
    address builder
  ) external onlyOwner {
    payloadBuilders[chainId][depository] = builder;
    emit PayloadBuilderSet(chainId, depository, builder);
  }

  /// @notice submits a withdraw request to the payload builder, stores the returned payload, and triggers its signature immediately. This will only work for payloads that require a single signature (including Bitcoin, which is now supported via the hashIndex parameter).
  /// @param params The withdraw request parameters
  /// @param signature The signature of the withdraw request, if sent on behalf of a recipient
  function submitAndSignWithdrawRequest(
    SubmitWithdrawRequest calldata params,
    bytes memory signature,
    GasSettings memory gasSettings
  ) public {
    _submitWithdrawRequest(params);
    signWithdrawPayloadHash(params, signature, gasSettings, 0);
  }

  /// @notice submits a withdraw request to the payload builder, store the returned payload
  /// @param params The withdraw request parameters
  /// @return withdrawRequestHash The hash of the withdrawal request
  function submitWithdrawRequest(
    SubmitWithdrawRequest calldata params
  ) public returns (bytes32 withdrawRequestHash) {
    return _submitWithdrawRequest(params);
  }

  /// @notice submits a withdraw request to the payload builder, store the returned payload
  /// @param params The withdraw request parameters
  /// @return withdrawRequestHash The hash of the withdrawal request
  function _submitWithdrawRequest(
    SubmitWithdrawRequest calldata params
  ) internal returns (bytes32 withdrawRequestHash) {
    // check if the payload builder is set
    address builder = payloadBuilders[params.chainId][params.depository];

    if (builder == address(0)) {
      revert NoPayloadBuilder(params.chainId, params.depository);
    }

    // build payload
    bytes memory payload = IPayloadBuilder(builder).buildPayload(
      params.chainId,
      params.depository,
      params.currency,
      params.amount,
      params.receiver,
      params.data
    );

    // Store the hash of the request for deduplication and verification
    withdrawRequestHash = keccak256(abi.encode(params));
    payloads[withdrawRequestHash] = payload;

    // Use depository-specific delay if set, otherwise fall back to global delay
    uint256 depositoryDelay = depositoryDelays[params.chainId][
      params.depository
    ].delay;
    uint256 effectiveDelay = depositoryDelays[params.chainId][params.depository]
      .isSet
      ? depositoryDelay
      : delay;

    // Only set timestamp if it hasn't been set before to prevent timestamp manipulation
    if (payloadTimestamps[withdrawRequestHash] != 0) {
      revert PayloadAlreadyBuilt(withdrawRequestHash);
    }

    payloadTimestamps[withdrawRequestHash] = block.timestamp + effectiveDelay;

    emit PayloadBuilt(
      withdrawRequestHash,
      payload,
      payloadTimestamps[withdrawRequestHash]
    );
    return withdrawRequestHash;
  }

  /// @notice triggers the signing of a previously submitted withdraw request
  /// @param params The withdraw request parameters (must match the stored hash)
  /// @param signature The signature of the withdraw request, if sent on behalf of a recipient
  /// @param gasSettings struct containing gas settings for NEAR operations
  /// @param hashIndex index of the hash to sign for this request
  /// @dev This function is called by the NEAR signer account to sign the payload.
  /// It checks if the payload is ready to be signed (i.e. the delay has passed) and
  /// if the payload has not already been signed. If the payload is ready, it calls
  /// the NEAR signer account to sign the payload and then calls the signWithdrawCallback
  /// function to handle the result of the signing.
  function signWithdrawPayloadHash(
    SubmitWithdrawRequest calldata params,
    bytes memory signature,
    GasSettings memory gasSettings,
    uint32 hashIndex
  ) public {
    if (signatureFee > 0) {
      // We capture the fee for ourselves first
      near.wNEAR.transferFrom(msg.sender, address(this), signatureFee);
    }

    bytes32 withdrawRequestHash = keccak256(abi.encode(params));

    // make sure the payload exists
    bytes memory payload = payloads[withdrawRequestHash];
    if (payload.length == 0) {
      revert PayloadNotReady(withdrawRequestHash);
    }

    // check if the payload is ready to be signed
    if (payloadTimestamps[withdrawRequestHash] > block.timestamp) {
      revert PayloadNotReady(withdrawRequestHash);
    }

    address builder = payloadBuilders[params.chainId][params.depository];
    IPayloadBuilder payloadBuilder = IPayloadBuilder(builder);

    // verify the withdrawal can be achieved
    verifyWithdrawal(params, payloadBuilder, signature);

    // get the hash to sign
    bytes32 hashToSign = payloadBuilder.hashToSign(
      params.chainId,
      params.depository,
      payload,
      hashIndex
    );

    _signUsingChainSignatures(
      withdrawRequestHash,
      hashToSign,
      payloadBuilder,
      gasSettings
    );
  }

  /// @notice withdraws the wNEAR balance of this contract
  /// from the Aurora contract to the NEAR network
  function withdrawToNear(uint256 amount) external {
    // withdraw wNEAR to the NEAR network
    IEvmERC20(address(near.wNEAR)).withdrawToNear(
      bytes(AuroraSdk.nearRepresentative(address(this))),
      amount
    );

    // unwrap the wNEAR on the NEAR network
    PromiseCreateArgs memory unwrapCall = near.call(
      "wrap.testnet",
      "near_withdraw",
      abi.encodePacked(
        // solhint-disable-next-line quotes
        '{"amount": "',
        Strings.toString(amount),
        // solhint-disable-next-line quotes
        '"}'
      ),
      1, // requires attached deposit of exactly 1 yoctoNEAR
      NEAR_WITHDRAW_GAS // nearGas
    );

    unwrapCall.transact();
  }

  /// @notice Signs a hash using chain signatures
  /// @param withdrawRequestHash The withdrawal request hash
  /// @param hashToSign The hash to sign
  /// @param payloadBuilder The payload builder
  /// @param gasSettings The gas settings for NEAR operations
  function _signUsingChainSignatures(
    bytes32 withdrawRequestHash,
    bytes32 hashToSign,
    IPayloadBuilder payloadBuilder,
    GasSettings memory gasSettings
  ) internal {
    if (signedPayloads[withdrawRequestHash][hashToSign].length > 0) {
      revert PayloadAlreadySigned(withdrawRequestHash);
    }
    // Encode the JSON request for the signer
    bytes memory data = ChainSignatures.encodeJSONRequest(
      ChainSignatures.stringifyBytes(abi.encodePacked(hashToSign)),
      payloadBuilder.curve(),
      signerPath,
      keccak256(abi.encodePacked(payloadBuilder.curve())) == ECDSA_HASH
        ? "0"
        : "1"
    );
    // Now get NEAR to sign the payload!
    PromiseCreateArgs memory callSign = near.call(
      nearSigner,
      "sign",
      data,
      // the docs here https://github.com/aurora-is-near/chain-signatures-signer/tree/main?tab=readme-ov-file#signing-the-payload
      // states that 1 yoctoNEAR is usually enough to sign the call successfully
      1, // attachedNear
      gasSettings.signGas
    );
    PromiseCreateArgs memory callback = near.auroraCall(
      address(this),
      abi.encodeWithSelector(
        this.signWithdrawCallback.selector,
        withdrawRequestHash,
        hashToSign
      ),
      0,
      gasSettings.callbackGas
    );
    callSign.then(callback).transact();
  }

  /// @notice callback function to handle the result of the signing
  /// @param withdrawRequestHash hash of the requested withdrawal payload that was signed
  /// @dev This function is called by the NEAR signer account after the signing is complete.
  /// It checks if the signing was successful and if so, stores the signed payload in the
  /// signedPayloads mapping. It also emits an event to notify that the payload has been signed.
  function signWithdrawCallback(
    bytes32 withdrawRequestHash,
    bytes32 hashToSign
  ) public {
    if (
      msg.sender != AuroraSdk.nearRepresentitiveImplicitAddress(address(this))
    ) {
      revert AccessControlUnauthorizedAccount(
        msg.sender,
        keccak256("SIGNATURE_CALLBACK_ROLE")
      );
    }
    // triggering this function requires Aurora precompiles and therefore has no unit tests
    PromiseResult memory result = AuroraSdk.promiseResult(0);

    if (result.status != PromiseResultStatus.Successful) {
      revert SignCallbackFailed(withdrawRequestHash);
    }

    signedPayloads[withdrawRequestHash][hashToSign] = result.output;
    emit PayloadWithdrawSigned(withdrawRequestHash, hashToSign, result.output);
  }

  /// @notice Verifies if the withdrawal request can be achieved.
  /// @dev The withdrawal can be achieved if the caller is an approved withdrawer, or,
  /// if the hub is set, it will first transfer the user's token to this contract's balance.
  /// @param params The withdrawal request parameters
  /// @param payloadBuilder The payload builder containing the withdrawal details
  /// @param signature A signature for the withdrawal request, if sent on behalf of a recipient
  function verifyWithdrawal(
    SubmitWithdrawRequest calldata params,
    IPayloadBuilder payloadBuilder,
    bytes memory signature
  ) internal {
    // Implementation for verifying the withdrawal
    if (hasRole(APPROVED_WITHDRAWER_ROLE, msg.sender)) {
      return;
    }

    string memory family = payloadBuilder.family();

    // Generate the tokenId
    uint256 tokenId = Utils.generateTokenId(
      family,
      params.chainId,
      params.currency
    );

    address spenderAlias = Utils.generateAddress(
      family,
      params.chainId,
      params.receiver
    );

    // Only an operator for the spender can trigger withdrawals or a valid signature by the recipient must be provided.
    if (
      !(params.spender == msg.sender ||
        RelayHub(hub).isOperator(params.spender, msg.sender) ||
        (spenderAlias == params.spender &&
          signatureMatchesReceiver(params, signature)))
    ) {
      revert CallerIsNotApproved(msg.sender);
    }

    // Actually perform the transfer
    RelayHub(hub).transferFrom(
      params.spender,
      address(this),
      tokenId,
      params.amount
    );
  }

  /// @notice Checks if the signature matches the receiver's address (for EVM destination chains)
  /// @param params The withdrawal request parameters
  /// @param signature The signature to verify
  /// @return True if the signature matches the receiver
  function signatureMatchesReceiver(
    SubmitWithdrawRequest memory params,
    bytes memory signature
  ) internal returns (bool) {
    if (signature.length == 0) return false;

    address signer = Utils.toAddress(params.receiver);

    // Check if nonce has been used before for this sender
    if (usedNonces[signer][params.nonce]) {
      return false;
    }

    // Create the digest using EIP712
    bytes32 digest = _hashTypedDataV4(
      keccak256(
        abi.encode(
          PAYLOAD_TYPEHASH,
          params.chainId,
          keccak256(bytes(params.depository)),
          keccak256(bytes(params.currency)),
          params.amount,
          params.spender,
          keccak256(bytes(params.receiver)),
          keccak256(params.data),
          params.nonce
        )
      )
    );

    if (digest.recover(signature) != signer) {
      return false;
    }

    // Mark nonce as used to prevent replay for this sender
    usedNonces[signer][params.nonce] = true;
    return true;
  }
}

contracts/RelayHub.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/Strings.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "./ERC20View.sol";

/// @title IERC20View
/// @author Relay Protocol
/// @notice Interface for ERC20View contract
interface IERC20View {
  /// @notice Emits a transfer event
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount transferred
  function emitTransferEvent(address from, address to, uint256 value) external;

  /// @notice Emits an approval event
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param value The approved amount
  function emitApprovalEvent(
    address owner,
    address spender,
    uint256 value
  ) external;
}

/// @title RelayHub
/// @author Relay Protocol
/// @notice Based on Solmate standard ERC6909 implementation. (https://github.com/transmissions11/solmate/blob/main/src/tokens/ERC6909.sol)
contract RelayHub is AccessControl, EIP712 {
  using Strings for uint256;

  /*//////////////////////////////////////////////////////////////
                            CUSTOM ERRORS
    //////////////////////////////////////////////////////////////*/

  /// @notice Error thrown when non-ERC20View tries to call approveFor
  /// @param caller The address that attempted to call approveFor
  /// @param expectedERC20View The expected ERC20View address for the token
  error OnlyERC20ViewCanCallApproveFor(
    address caller,
    address expectedERC20View
  );

  /// @notice Error thrown when permit deadline has expired
  error PermitDeadlineExpired();

  /// @notice Error thrown when permit signature is invalid
  error InvalidPermitSignature();

  /// @notice Error thrown when permit owner is the zero address
  error InvalidPermitOwner();

  /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an operator is set for an owner
  event OperatorSet(
    address indexed owner,
    address indexed operator,
    bool approved
  );

  /// @notice Emitted when an approval is made
  event Approval(
    address indexed owner,
    address indexed spender,
    uint256 indexed id,
    uint256 amount
  );

  /// @notice Emitted when a transfer occurs
  event Transfer(
    address caller,
    address indexed from,
    address indexed to,
    uint256 indexed id,
    uint256 amount
  );

  struct TokenMetadata {
    string name;
    string symbol;
    uint8 decimals;
    string originFamily;
    uint256 originChainId;
    string originAsset;
  }

  /*//////////////////////////////////////////////////////////////
                             ERC6909 STORAGE
    //////////////////////////////////////////////////////////////*/

  mapping(address => mapping(address => bool)) internal _isOperator;

  /// @notice Mapping of owner to token ID to balance
  mapping(address => mapping(uint256 => uint256)) public balanceOf;

  /// @notice Mapping of owner to spender to token ID to allowance
  mapping(address => mapping(address => mapping(uint256 => uint256)))
    public allowance;

  /// @notice Mapping of token ID to total supply
  mapping(uint256 => uint256) public totalSupply;

  /// @notice Mapping of owner to nonce for permit signatures
  mapping(address => uint256) public nonces;

  /*//////////////////////////////////////////////////////////////
                          ERC20VIEW STORAGE
    //////////////////////////////////////////////////////////////*/

  // tokenId => ERC20View address
  /// @notice Mapping of token ID to ERC20View contract address
  mapping(uint256 => address) public erc20Views;

  /*//////////////////////////////////////////////////////////////
                        ERC20VIEW EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an ERC20View is created
  event ERC20ViewCreated(uint256 indexed tokenId, address indexed erc20View);
  /// @notice Mapping of token ID to token metadata
  mapping(uint256 => TokenMetadata) public tokenMetadata;

  /// @notice Contract URI for metadata
  string public contractURI = "";

  /*//////////////////////////////////////////////////////////////
                             ROLES
    //////////////////////////////////////////////////////////////*/

  /// @notice Role for operators
  bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
  /// @notice Role for editors
  bytes32 public constant EDITOR_ROLE = keccak256("EDITOR_ROLE");
  /// @notice Role for administrators
  bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

  /*//////////////////////////////////////////////////////////////
                          EIP712 CONSTANTS
    //////////////////////////////////////////////////////////////*/

  /// @notice EIP712 typehash for permit
  bytes32 public constant PERMIT_TYPEHASH =
    keccak256(
      "Permit(address owner,address spender,uint256 tokenId,uint256 value,uint256 nonce,uint256 deadline)"
    );

  /*//////////////////////////////////////////////////////////////
                             CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

  /// @notice Constructor for RelayHub contract
  /// @param adminAddress The address to grant admin role
  constructor(address adminAddress) EIP712("RelayHub", "1") {
    _setRoleAdmin(OPERATOR_ROLE, ADMIN_ROLE);
    _setRoleAdmin(EDITOR_ROLE, ADMIN_ROLE);
    _setRoleAdmin(ADMIN_ROLE, ADMIN_ROLE);
    _grantRole(ADMIN_ROLE, adminAddress);
  }

  /*//////////////////////////////////////////////////////////////
                              ERC6909 LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Checks if an address is an operator for an account
  /// @param account The account address
  /// @param operator The operator address
  /// @return True if the operator is authorized
  function isOperator(
    address account,
    address operator
  ) public view returns (bool) {
    return hasRole(OPERATOR_ROLE, operator) || _isOperator[account][operator];
  }

  /// @notice Internal function to set an operator for an account
  /// @param account The account address
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function _setOperatorFor(
    address account,
    address operator,
    bool approved
  ) internal returns (bool result) {
    _isOperator[account][operator] = approved;
    emit OperatorSet(account, operator, approved);
    return true;
  }

  /// @notice Sets an operator for an account (only callable by OPERATOR_ROLE)
  /// @param account The account address
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function setOperatorFor(
    address account,
    address operator,
    bool approved
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    return _setOperatorFor(account, operator, approved);
  }

  /// @notice Sets an operator for the caller
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function setOperator(
    address operator,
    bool approved
  ) public returns (bool result) {
    return _setOperatorFor(msg.sender, operator, approved);
  }

  /// @notice Transfers tokens to another address
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return result True if successful
  function transfer(
    address receiver,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    balanceOf[msg.sender][id] -= amount;

    balanceOf[receiver][id] += amount;

    emit Transfer(msg.sender, msg.sender, receiver, id, amount);
    _emitERC20ViewEvent(id, msg.sender, receiver, amount);

    return true;
  }

  /// @notice Transfers tokens from one address to another
  /// @param sender The sender address
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return result True if successful
  function transferFrom(
    address sender,
    address receiver,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    if (
      msg.sender != sender &&
      !isOperator(sender, msg.sender) &&
      erc20Views[id] != msg.sender
    ) {
      uint256 allowed = allowance[sender][msg.sender][id];
      if (allowed != type(uint256).max)
        allowance[sender][msg.sender][id] = allowed - amount;
    }

    balanceOf[sender][id] -= amount;

    balanceOf[receiver][id] += amount;

    emit Transfer(msg.sender, sender, receiver, id, amount);
    _emitERC20ViewEvent(id, sender, receiver, amount);

    return true;
  }

  /// @notice Approves a spender to spend tokens
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return result True if successful
  function approve(
    address spender,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    allowance[msg.sender][spender][id] = amount;

    emit Approval(msg.sender, spender, id, amount);
    _emitERC20ViewApprovalEvent(id, msg.sender, spender, amount);

    return true;
  }

  /// @notice Approves a spender to spend tokens on behalf of owner (only callable by ERC20View)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return result True if successful
  function approveFor(
    address owner,
    address spender,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    if (erc20Views[id] != msg.sender) {
      revert OnlyERC20ViewCanCallApproveFor(msg.sender, erc20Views[id]);
    }

    allowance[owner][spender][id] = amount;

    emit Approval(owner, spender, id, amount);
    // Note: The ERC20View will emit its own Approval event

    return true;
  }

  /// @notice Permits a spender to spend tokens via signature (EIP712)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param tokenId The token ID
  /// @param value The allowance amount
  /// @param deadline The deadline timestamp
  /// @param v The recovery byte of the signature
  /// @param r Half of the ECDSA signature pair
  /// @param s Half of the ECDSA signature pair
  function permit(
    address owner,
    address spender,
    uint256 tokenId,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) public {
    if (owner == address(0)) {
      revert InvalidPermitOwner();
    }

    if (block.timestamp > deadline) {
      revert PermitDeadlineExpired();
    }

    uint256 ownerNonce = nonces[owner];

    bytes32 structHash = keccak256(
      abi.encode(
        PERMIT_TYPEHASH,
        owner,
        spender,
        tokenId,
        value,
        ownerNonce,
        deadline
      )
    );

    bytes32 hash = _hashTypedDataV4(structHash);

    address signer = ECDSA.recover(hash, v, r, s);

    if (signer != owner) {
      revert InvalidPermitSignature();
    }

    nonces[owner] = ownerNonce + 1;

    allowance[owner][spender][tokenId] = value;

    emit Approval(owner, spender, tokenId, value);
    _emitERC20ViewApprovalEvent(tokenId, owner, spender, value);
  }

  /// @notice Mints tokens to a receiver (only callable by OPERATOR_ROLE)
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to mint
  /// @return result True if successful
  function mint(
    address receiver,
    uint256 id,
    uint256 amount
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    _mint(receiver, id, amount);
    return true;
  }

  /// @notice Burns tokens from a sender (only callable by OPERATOR_ROLE)
  /// @param sender The sender address
  /// @param id The token ID
  /// @param amount The amount to burn
  /// @return result True if successful
  function burn(
    address sender,
    uint256 id,
    uint256 amount
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    _burn(sender, id, amount);
    return true;
  }

  /// @notice Sets token metadata (only callable by EDITOR_ROLE)
  /// @param id The token ID
  /// @param metadata The token metadata
  function setTokenMetadata(
    uint256 id,
    TokenMetadata calldata metadata
  ) public onlyRole(EDITOR_ROLE) {
    tokenMetadata[id] = metadata;
  }

  /// @notice Returns the name of a token
  /// @param id The token ID
  /// @return The token name
  function name(uint256 id) public view returns (string memory) {
    return tokenMetadata[id].name;
  }

  /// @notice Returns the symbol of a token
  /// @param id The token ID
  /// @return The token symbol
  function symbol(uint256 id) public view returns (string memory) {
    return tokenMetadata[id].symbol;
  }

  /// @notice Returns the decimals of a token
  /// @param id The token ID
  /// @return The token decimals
  function decimals(uint256 id) public view returns (uint8) {
    if (tokenMetadata[id].decimals == 0) {
      return 18;
    }
    return tokenMetadata[id].decimals;
  }

  /// @notice Sets the contract URI (only callable by EDITOR_ROLE)
  /// @param uri The contract URI
  function setContractURI(string calldata uri) public onlyRole(EDITOR_ROLE) {
    contractURI = uri;
  }

  /// @notice Returns the token URI
  /// @param id The token ID
  /// @return The token URI
  function tokenURI(uint256 id) public view returns (string memory) {
    return string.concat(contractURI, "/", id.toString());
  }

  /*//////////////////////////////////////////////////////////////
                              ERC165 LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Returns the domain separator for EIP712
  /// @return The domain separator
  function DOMAIN_SEPARATOR() external view returns (bytes32) {
    return _domainSeparatorV4();
  }

  /// @notice Checks if the contract supports an interface
  /// @param interfaceId The interface ID to check
  /// @return result True if the interface is supported
  function supportsInterface(
    bytes4 interfaceId
  ) public pure override(AccessControl) returns (bool result) {
    return
      interfaceId == 0x01ffc9a7 || // ERC165 Interface ID for ERC165
      interfaceId == 0x0f632fb3; // ERC165 Interface ID for ERC6909
  }

  /*//////////////////////////////////////////////////////////////
                        INTERNAL MINT/BURN LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Internal function to mint tokens
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to mint
  function _mint(address receiver, uint256 id, uint256 amount) internal {
    balanceOf[receiver][id] += amount;
    if (totalSupply[id] == 0) {
      _createERC20View(id);
    }
    totalSupply[id] += amount;

    emit Transfer(msg.sender, address(0), receiver, id, amount);
    _emitERC20ViewEvent(id, address(0), receiver, amount);
  }

  /// @notice Internal function to burn tokens
  /// @param sender The sender address
  /// @param id The token ID
  /// @param amount The amount to burn
  function _burn(address sender, uint256 id, uint256 amount) internal {
    balanceOf[sender][id] -= amount;
    totalSupply[id] -= amount;

    emit Transfer(msg.sender, sender, address(0), id, amount);
    _emitERC20ViewEvent(id, sender, address(0), amount);
  }

  /*//////////////////////////////////////////////////////////////
                            INTERNAL HELPERS
  //////////////////////////////////////////////////////////////*/

  /// @notice Internal function to emit ERC20View events
  /// @param id The token ID
  /// @param from The sender address
  /// @param to The recipient address
  /// @param amount The amount transferred
  function _emitERC20ViewEvent(
    uint256 id,
    address from,
    address to,
    uint256 amount
  ) internal {
    address erc20ViewAddress = erc20Views[id];
    if (msg.sender != erc20ViewAddress) {
      IERC20View(erc20ViewAddress).emitTransferEvent(from, to, amount);
    }
  }

  /// @notice Internal function to emit ERC20View approval events
  /// @param id The token ID
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param amount The approved amount
  function _emitERC20ViewApprovalEvent(
    uint256 id,
    address owner,
    address spender,
    uint256 amount
  ) internal {
    address erc20ViewAddress = erc20Views[id];
    if (msg.sender != erc20ViewAddress) {
      IERC20View(erc20ViewAddress).emitApprovalEvent(owner, spender, amount);
    }
  }

  /// @notice Internal function to create an ERC20View contract
  /// @param tokenId The token ID
  /// @return The address of the created ERC20View contract
  function _createERC20View(uint256 tokenId) internal returns (address) {
    if (erc20Views[tokenId] != address(0)) {
      return erc20Views[tokenId];
    }

    ERC20View erc20View = new ERC20View(tokenId);

    address erc20ViewAddress = address(erc20View);
    erc20Views[tokenId] = erc20ViewAddress;

    emit ERC20ViewCreated(tokenId, erc20ViewAddress);
    return erc20ViewAddress;
  }
}

